use desktop_design_system::is_system_dark_mode;
use slint::VecModel;
use std::cell::RefCell;
use std::rc::Rc;

// Include the isolated example UI generated by build.rs
include!(concat!(env!("OUT_DIR"), "/crypto_tracker.rs"));

#[derive(Clone)]
struct CoinState {
    symbol: &'static str,
    name: &'static str,
    base_price: f64,
    current_price: f64,
    change_pct: f64,
    volume: &'static str,
    high: f64,
    low: f64,
}

fn main() -> Result<(), slint::PlatformError> {
    let app = CryptoTrackerWindow::new()?;

    // 1. Theme sync with OS
    app.global::<Palette>().set_dark_mode(is_system_dark_mode());

    // 2. Initial Coins Data
    let coins = Rc::new(RefCell::new(vec![
        CoinState { symbol: "BTC", name: "Bitcoin", base_price: 68450.0, current_price: 68450.0, change_pct: 3.45, volume: "$28.4B", high: 69100.0, low: 67200.0 },
        CoinState { symbol: "ETH", name: "Ethereum", base_price: 3540.2, current_price: 3540.2, change_pct: 2.12, volume: "$14.1B", high: 3620.0, low: 3480.0 },
        CoinState { symbol: "SOL", name: "Solana", base_price: 182.4, current_price: 182.4, change_pct: 6.80, volume: "$5.8B", high: 188.0, low: 174.0 },
        CoinState { symbol: "RUST", name: "RustCoin", base_price: 42.5, current_price: 42.5, change_pct: 15.20, volume: "$1.2B", high: 45.0, low: 36.0 },
        CoinState { symbol: "AVAX", name: "Avalanche", base_price: 34.1, current_price: 34.1, change_pct: -1.45, volume: "$840M", high: 35.8, low: 33.2 },
        CoinState { symbol: "LINK", name: "Chainlink", base_price: 14.8, current_price: 14.8, change_pct: 0.95, volume: "$620M", high: 15.4, low: 14.2 },
        CoinState { symbol: "DOT", name: "Polkadot", base_price: 7.2, current_price: 7.2, change_pct: -2.30, volume: "$380M", high: 7.6, low: 7.0 },
        CoinState { symbol: "ADA", name: "Cardano", base_price: 0.45, current_price: 0.45, change_pct: 1.10, volume: "$410M", high: 0.48, low: 0.43 },
    ]));

    // Helper to push state to UI
    let push_rows_to_ui = {
        let app_weak = app.as_weak();
        let coins_ref = coins.clone();
        move || {
            if let Some(app) = app_weak.upgrade() {
                let borrowed = coins_ref.borrow();
                let rows: Vec<CryptoRow> = borrowed.iter().map(|c| {
                    let sign = if c.change_pct >= 0.0 { "+" } else { "" };
                    CryptoRow {
                        symbol: c.symbol.into(),
                        name: c.name.into(),
                        price: if c.current_price >= 1.0 {
                            format!("${:.2}", c.current_price).into()
                        } else {
                            format!("${:.4}", c.current_price).into()
                        },
                        change_pct: format!("{}{:.2}%", sign, c.change_pct).into(),
                        is_positive: c.change_pct >= 0.0,
                        volume_24h: c.volume.into(),
                        high_24h: format!("${:.2}", c.high).into(),
                        low_24h: format!("${:.2}", c.low).into(),
                    }
                }).collect();

                let model = Rc::new(VecModel::from(rows));
                app.set_crypto_rows(model.into());

                // Update Top Cards
                if let Some(btc) = borrowed.iter().find(|c| c.symbol == "BTC") {
                    app.set_btc_price(format!("${:.2}", btc.current_price).into());
                    app.set_btc_change(format!("+{:.2}%", btc.change_pct).into());
                }
                if let Some(eth) = borrowed.iter().find(|c| c.symbol == "ETH") {
                    app.set_eth_price(format!("${:.2}", eth.current_price).into());
                    app.set_eth_change(format!("+{:.2}%", eth.change_pct).into());
                }
                if let Some(sol) = borrowed.iter().find(|c| c.symbol == "SOL") {
                    app.set_sol_price(format!("${:.2}", sol.current_price).into());
                    app.set_sol_change(format!("+{:.2}%", sol.change_pct).into());
                }
                if let Some(rust) = borrowed.iter().find(|c| c.symbol == "RUST") {
                    app.set_rust_price(format!("${:.2}", rust.current_price).into());
                    app.set_rust_change(format!("+{:.2}%", rust.change_pct).into());
                }
            }
        }
    };

    // Initial render
    push_rows_to_ui();

    // 3. Dynamic Ticker Timer
    let timer = Rc::new(RefCell::new(slint::Timer::default()));
    let interval_ms = Rc::new(RefCell::new(1000u64));
    let is_paused = Rc::new(RefCell::new(false));

    let start_ticker_loop = {
        let timer_clone = timer.clone();
        let coins_clone = coins.clone();
        let app_weak = app.as_weak();
        let interval_ref = interval_ms.clone();
        let is_paused_ref = is_paused.clone();

        move || {
            let app_weak_tick = app_weak.clone();
            let coins_tick = coins_clone.clone();
            let is_paused_tick = is_paused_ref.clone();
            let dur = std::time::Duration::from_millis(*interval_ref.borrow());

            timer_clone.borrow_mut().start(
                slint::TimerMode::Repeated,
                dur,
                move || {
                    if *is_paused_tick.borrow() {
                        return;
                    }
                    let t0 = std::time::Instant::now();

                    // Micro-volatility price calculation
                    {
                        let mut borrowed = coins_tick.borrow_mut();
                        for (idx, coin) in borrowed.iter_mut().enumerate() {
                            let delta = ((idx as f64 * 1.7 + 0.3).sin() * 0.0035) * coin.base_price;
                            coin.current_price = (coin.current_price + delta).max(0.01);
                            coin.change_pct += delta / coin.base_price * 100.0;
                            coin.high = coin.high.max(coin.current_price);
                            coin.low = coin.low.min(coin.current_price);
                        }
                    }

                    // Push to Slint UI
                    if let Some(app) = app_weak_tick.upgrade() {
                        let borrowed = coins_tick.borrow();
                        let rows: Vec<CryptoRow> = borrowed.iter().map(|c| {
                            let sign = if c.change_pct >= 0.0 { "+" } else { "" };
                            CryptoRow {
                                symbol: c.symbol.into(),
                                name: c.name.into(),
                                price: if c.current_price >= 1.0 {
                                    format!("${:.2}", c.current_price).into()
                                } else {
                                    format!("${:.4}", c.current_price).into()
                                },
                                change_pct: format!("{}{:.2}%", sign, c.change_pct).into(),
                                is_positive: c.change_pct >= 0.0,
                                volume_24h: c.volume.into(),
                                high_24h: format!("${:.2}", c.high).into(),
                                low_24h: format!("${:.2}", c.low).into(),
                            }
                        }).collect();

                        let model = Rc::new(VecModel::from(rows));
                        app.set_crypto_rows(model.into());

                        // Measure latency
                        let elapsed_micros = t0.elapsed().as_micros();
                        app.set_latency_ms(format!("{:.1} ms", (elapsed_micros as f64) / 1000.0).into());
                    }
                },
            );
        }
    };

    // Start timer at 1.0s
    start_ticker_loop();

    // 4. Connect Callbacks
    let app_weak_speed = app.as_weak();
    let interval_speed = interval_ms.clone();
    let start_speed = start_ticker_loop.clone();
    app.on_set_interval_speed(move |mode| {
        let (ms, label) = match mode {
            1 => (1000, "1.0s (Ultra-Fast)"),
            2 => (3000, "3.0s (Standard)"),
            _ => (10000, "10.0s (Battery Saver)"),
        };
        *interval_speed.borrow_mut() = ms;
        if let Some(app) = app_weak_speed.upgrade() {
            app.set_interval_label(label.into());
            start_speed();
        }
    });

    let app_weak_pause = app.as_weak();
    let is_paused_cb = is_paused.clone();
    app.on_toggle_pause(move || {
        let next = !*is_paused_cb.borrow();
        *is_paused_cb.borrow_mut() = next;
        if let Some(app) = app_weak_pause.upgrade() {
            app.set_is_paused(next);
        }
    });

    let app_weak_toast = app.as_weak();
    app.on_trigger_order(move |sym, price| {
        if let Some(app) = app_weak_toast.upgrade() {
            app.set_toast_title(format!("Price Alert Set ({})", sym).into());
            app.set_toast_msg(format!("Target trigger logged at {} on local SQLite index.", price).into());
            app.set_toast_status("success".into());
            app.set_toast_open(true);
        }
    });

    let _keep_alive = timer;
    app.run()
}
